  "help.chitMaxLoss": "हमनी के सुझाव बा कि रउरा आमदनी, मासिक बकाया, खुला कर्ज, ओवरड्यू बिल, आ बचत से अधिकतम नुकसान — फिक्स % ना. जल्दी ले लिहल अक्सर एकरा से अधिका हो जाला; बाद के महीना में आमतौर पर कम लागत आवेला.",
  "help.loanExtraTiming": "आवे वाला महीना देखावेला: जब दोसर बिल हल्का होखे ताकि रउआ एह लोन प अतिरिक्त भुगतान कर सकीले, अवुरी भारी महीना जब रउआ न्यूनतम प अडिग रहे के चाही।",
  "help.incomeEntryBasis": "टेक-होम टैक्स, PF, आ फिक्स्ड कटौती के बाद आपके बैंक में जवन उतरेला ओकरा से मेल खाला — दबाव आ मुफ्त-कैश गणित खातिर सबसे बढ़िया। सकल तबे उपयोगी होला जब रउआँ द्वारा दर्ज कइल गइल हर नंबर कर से पहिले के होखे; मुफ्त नकदी रउरा वास्तविक बैंक बैलेंस से कम लउक सकेला अगर टेक-होम आय सकल से कम होखे.",
