  "wealthDetail.property.narrative.vsBenchmarkExplain": "Your {cagr}% CAGR vs ~{benchmark}% typical for this city tier ({delta}% difference) — use as a rough peer check, not a buy/sell signal.",
  "wealthDetail.property.narrative.longHoldLiquidity": "लंबा होल्ड से टाइमिंग रिस्क कम हो जाला लेकिन लॉक कैपिटल — एकरा के बेचे लायक धन के रूप में माने से पहिले 6-12 महीना के खर्चा के कहीं अवुरी तरल राखे के चाही।",
  "wealthDetail.property.narrative.rentYieldExplain": "Estimated gross rent yield ~{yield}% — compare with FD/PPF after tax; if you live in the property, treat rent savings as implicit yield.",
  "wealthDetail.property.narrative.rentVsIncome": "अगर पूरा तरह से किराया पर लिहल जाव त सकल किराया रउरा घोषित मासिक आय के ~{pct}% होखी — जांच करीं कि ऊ रउरा वास्तविक भा हासिल करे लायक किराया से मेल खात बा कि ना.",
  "wealthDetail.property.narrative.valueVsIncome": "ई संपत्ति ~{multiple}× कागज पर राउर सालाना आय बा — एगो बड़हन एकाग्रता; आपातकालीन आ विविधीकरण योजना में कि कारक.",
  "wealthDetail.property.narrative.highValueTier3Liquidity": "छोट शहर में एह मान पर, खरीददार खोजे में महीना भर लाग सके ला — यथार्थवादी तरीका से कीमत आ पूरा मूल्य के तुरंत उपलब्ध नकदी के रूप में गिने से बचे के चाहीं।",
  "wealthDetail.property.narrative.highValueTier2Liquidity": "टीयर-2 बाजार खातिर उच्च टिकट — अपना बतावल मूल्य पर त्वरित तरलता मानला से पहिले पास में हाल के पंजीकृत बिक्री के सत्यापन करीं।",
  "wealthDetail.property.narrative.targetCagrReality": "इहाँ से 12% CAGR के पीछा करे में आज के गति से ~{years} अउरी साल लागी — राउर होल्डिंग पहिलहीं से मजबूत नाममात्र के लाभ देले रहे; भविष्य के रिटर्न सामान्य हो सकेला.",
  "wealthDetail.property.narrative.landHold": "जमीन: सबसे कम रखरखाव लेकिन सबसे धीमा तरलता — 10+ साल के क्षितिज खातिर सबसे अच्छा; लिस्टिंग से पहिले भार, जोनिंग, आ सड़क चौड़ा करे के सूचना के जांच करीं.",
  "wealthDetail.property.narrative.commercialHold": "व्यावसायिक: रिक्ति आ किरायेदार के गुणवत्ता ओतने मायने राखेला जतना कि स्थान — अगर फुटफाल भा पट्टा के शर्त कमजोर हो जाव त फेर से आकलन करीं.",
  "wealthDetail.property.narrative.residentialHold": "आवासीय: स्व-उपयोग से बेचे के दबाव कम हो जाला; अगर किराया पर लिहल जाव त किरायेदारन के कारोबार आ समाज के रखरखाव में बढ़ोतरी के ट्रैक करीं.",
  "wealthDetail.property.narrative.verifyTitle": "कवनो बिक्री से पहिले: भार प्रमाणपत्र, संपत्ति कर के रसीद, आ उत्परिवर्तन के स्थिति — इहाँ देरी से कागजी लाभ के मेटावल जाला।",
